{
  "scenario": "C15-OUT1-positive-ready-set-r16",
  "checklist": [
    {
      "id": "CL-1",
      "description": "candidate は confirmed/pass/readiness complete、全 depends_on done、active lease なしを満たす",
      "status": "pass",
      "evidence": "Ready set = [LT-SCHED-001, LT-SCHED-002, LT-SCHED-003, LT-SCHED-006]. All have confirmation_status=confirmed, evaluation_status=pass, implementation_readiness.status=complete, depends_on=[] (empty or all done), no active lease. LT-SCHED-004 excluded (active lease expires 2099). LT-SCHED-005 excluded (depends_on LT-SCHED-001 which is open)."
    },
    {
      "id": "CL-2",
      "description": "feature ready と task ready が別々の ready-set/batch に出力される",
      "status": "pass",
      "evidence": "batches.features=[] (empty), batches.tasks=[[LT-SCHED-001,LT-SCHED-003],[LT-SCHED-002,LT-SCHED-006]]. All nodes are artifact_kind=task. No feature nodes exist in fixture. Feature and task batches are structurally separated."
    },
    {
      "id": "CL-3",
      "description": "同一 parallel batch の resource_scope.touches 重複 pair が0件である",
      "status": "pass",
      "evidence": "Batch 0: LT-SCHED-001(src/alpha.py) + LT-SCHED-003(src/beta.py) — intersection empty. Batch 1: LT-SCHED-002(src/alpha.py) + LT-SCHED-006(src/delta.py) — intersection empty. LT-SCHED-001 and LT-SCHED-002 (both src/alpha.py) are in different batches. Conflict pair recorded in receipt."
    },
    {
      "id": "CL-4",
      "description": "各 task の suggested_branch が devgraph/<graph_node_id> で claim command が public CLI 形式である",
      "status": "pass",
      "evidence": "assignment_hints: devgraph/LT-SCHED-001, devgraph/LT-SCHED-002, devgraph/LT-SCHED-003, devgraph/LT-SCHED-006. All unique. Claim commands follow '/dev-graph worktree claim <id> --branch devgraph/<id> --session-id <session>' format."
    },
    {
      "id": "CL-5",
      "description": "実行前後の graph/tracker/lease digest が同一である",
      "status": "pass",
      "evidence": "graph_sha256_before=graph_sha256_after=c2b94b6c9450ef7d35b9fa0edc4a561ef1c66ce4acc96a31a3f81a2544d9ef1a. lease_sha256_before=lease_sha256_after=b10e1c1670e6cf36ca3155b2d390bdbd45183fff76b04c91c562d9f1f8c32b41. Independently verified with shasum."
    },
    {
      "id": "CL-6",
      "description": "lease pathがgit common-dirの正本と一致し、Beads receiptのstatus/depends_on exact-setが現在graphに一致する",
      "status": "pass",
      "evidence": "lease_source=git_common_dir. Lease path: .git/dev-graph/leases.json matches coordination_paths.leases from resolve-repo-context.py. All nodes have tracker_binding=none so Beads receipt is N/A; local gate used instead. Node status/depends_on in execution receipt match graph.json exactly."
    },
    {
      "id": "CL-7",
      "description": "C17独立verifierがready/batch/lease authorityを再計算してPASSしている",
      "status": "pass",
      "evidence": "dev-graph-parallel-safety-verifier returned verdict=PASS on all 6 checks: ready_set_correctness, batch_safety, lease_authority, max_parallel, branch_claim_uniqueness, digest_invariance. No unsafe pairs found."
    }
  ],
  "required_observations": [
    {
      "id": "OBS-1",
      "description": "the overlapping resource_scope pair is never placed in the same batch",
      "status": "pass",
      "evidence": "LT-SCHED-001 and LT-SCHED-002 both touch src/alpha.py. They are in batch 0 and batch 1 respectively. Conflict pair recorded."
    },
    {
      "id": "OBS-2",
      "description": "the blocked task is excluded from the ready set and the reason is reported",
      "status": "pass",
      "evidence": "LT-SCHED-005 excluded. unmapped entry: reason=dependency_unsatisfied, blocking_depends_on=[LT-SCHED-001]."
    },
    {
      "id": "OBS-3",
      "description": "the active lease suppresses its task while the stale lease is reclaimed",
      "status": "pass",
      "evidence": "LT-SCHED-004 (active lease expires 2099) excluded from ready set, listed in conflicts. LT-SCHED-006 (stale lease expired 2020) included in ready set — reclaimed."
    },
    {
      "id": "OBS-4",
      "description": "batches respect --max-parallel and suggested_branch and worktree claim commands stay unique",
      "status": "pass",
      "evidence": "max_parallel=2. Batch 0 size=2, Batch 1 size=2. All 4 suggested_branch and claim_command values are unique."
    }
  ]
}

